import pytest
from jinja2 import Environment

@pytest.fixture
def env_async():
    return Environment(enable_async=True)

@pytest.fixture
def foo():
    return lambda: [1, 2, 3]

def test_custom_filter_coroutine_error(env_async, foo):
    env_async.filters.update({'add_two': lambda x, y: [i + y for i in x]})
    tmpl = env_async.from_string("{% for item in (foo()|add_two(5))[:1] %}{{ item }}{% endfor %}")
    with pytest.raises(TypeError, match="'coroutine' object is not subscriptable"):
        tmpl.render(foo=foo)
